INSERT INTO training_exercises(id,name_fa,name_en,equipment,tags,instruction_fa,instruction_en,alternatives,illustration,source) VALUES
('wall-push-up','شنا روی دیوار','Wall push-up','bodyweight',ARRAY['chest'],'دست‌ها را روی دیوار بگذار؛ بدن را یکپارچه نگه دار و آرنج‌ها را با کنترل خم و باز کن.','Place your hands on a wall, keep your body aligned, and bend and extend your elbows with control.',ARRAY['push-up'],'/images/exercises/push-up.svg','Original Gym4Me exercise description.'),
('glute-bridge','پل باسن','Glute bridge','bodyweight',ARRAY['legs'],'به پشت دراز بکش و زانوها را خم کن؛ با تکیه بر کف پا لگن را آرام بالا ببر و پایین بیاور.','Lie on your back with knees bent. Press through your feet to slowly lift and lower your hips.',ARRAY['squat'],'/images/exercises/dead-bug.svg','Original Gym4Me exercise description.'),
('calf-raise','بالا آمدن روی پنجه','Calf raise','bodyweight',ARRAY['legs'],'کنار تکیه‌گاه پایدار بایست؛ پاشنه‌ها را آرام بالا ببر و با کنترل پایین بیاور.','Stand beside a stable support. Slowly lift your heels and lower them with control.',ARRAY['march'],'/images/exercises/march.svg','Original Gym4Me exercise description.'),
('side-step','گام به کنار','Side step','bodyweight',ARRAY['cardio'],'در فضای آزاد با گام‌های کوتاه به کنار حرکت کن و پاها را آرام کنار هم بیاور.','In a clear space, take short steps sideways and gently bring your feet together.',ARRAY['march'],'/images/exercises/march.svg','Original Gym4Me exercise description.'),
('sit-to-stand','نشستن و برخاستن','Sit to stand','bodyweight',ARRAY['legs'],'از صندلی ثابت استفاده کن؛ با کنترل بلند شو و آرام بنشین.','Use a stable chair. Stand up with control and sit down slowly.',ARRAY['squat'],'/images/exercises/squat.svg','Original Gym4Me exercise description.'),
('standing-leg-curl','خم کردن زانو ایستاده','Standing leg curl','bodyweight',ARRAY['legs'],'کنار تکیه‌گاه بایست؛ زانو را آرام خم کن و پاشنه را به پشت ببر، سپس پا را پایین بیاور.','Stand beside a support. Slowly bend one knee to bring your heel behind you, then lower your foot.',ARRAY['calf-raise'],'/images/exercises/march.svg','Original Gym4Me exercise description.'),
('heel-tap','تماس پاشنه','Heel tap','bodyweight',ARRAY['core'],'به پشت و با زانوهای خم دراز بکش؛ پاشنه‌ها را یکی‌درمیان با کنترل به زمین نزدیک کن.','Lie on your back with bent knees. Alternate lowering each heel toward the floor with control.',ARRAY['dead-bug'],'/images/exercises/dead-bug.svg','Original Gym4Me exercise description.'),
('standing-hip-abduction','باز کردن پا به کنار','Standing hip abduction','bodyweight',ARRAY['legs'],'کنار تکیه‌گاه پایدار بایست؛ یک پا را با دامنه راحت به کنار ببر و آرام برگردان.','Stand beside a stable support. Move one leg sideways through a comfortable range and return slowly.',ARRAY['side-step'],'/images/exercises/march.svg','Original Gym4Me exercise description.');
