ALTER TABLE training_exercises ADD COLUMN video_caption_fa text, ADD COLUMN video_caption_en text;
UPDATE training_exercises SET video_url='/videos/exercises/'||id||'.mp4',video_source='Gym4Me original schematic movement animation, 2026; not a filmed technique demonstration.',video_caption_fa='/videos/exercises/'||id||'.fa.vtt',video_caption_en='/videos/exercises/'||id||'.en.vtt',video_revision=video_revision+1 WHERE id IN ('squat','march','wall-push-up','glute-bridge') AND video_url IS NULL;
